import re
from typing import List, Dict, Any

# --------------------------------------------------------------------------- #
#  Helper utilities (assumed to exist but we provide fallbacks)
# --------------------------------------------------------------------------- #
def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
    """Return the node with the given title, or None."""
    for node in doc.get("nodes", []):
        if node.get("title") == title:
            return node
    return None

def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Return child nodes of the given node."""
    if not node:
        return []
    ids = node.get("children", [])
    return [n for n in doc.get("nodes", []) if n.get("node_id") in ids]

def scope_nodes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all descendant nodes of a scope node."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    result = []

    def collect(n):
        result.append(n)
        for child in children(doc, n):
            collect(child)

    for child in children(doc, scope_node):
        collect(child)
    return result

# --------------------------------------------------------------------------- #
#  Core functions required by the task
# --------------------------------------------------------------------------- #
def _parse_objects(lines: List[str]) -> Dict[str, str]:
    """
    Parse the 'Video #: Objects' list lines.
    Return a mapping from entity id ("Object N") to a human‑readable description.
    """
    entities = {}
    for line in lines:
        # Example: 'Object 0: gray rubber sphere (color=gray, …)'
        m = re.match(r'Object (\d+):\s*(.+?)\s*\(.*\)', line)
        if not m:
            m = re.match(r'Object (\d+):\s*(.+)', line)  # fallback
        if m:
            obj_id = f"Object {m.group(1)}"
            desc = m.group(2).strip()
            entities[obj_id] = desc
    return entities

def _object_ids_from_lines(lines: List[str]) -> List[str]:
    """Extract all 'Object N' ids appearing in a line."""
    return [f"Object {m.group(1)}" for m in re.finditer(r'Object (\d+)', ' '.join(lines))]

def _parse_motion_log_table(table: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    Parse the motion log table. Return list of records with numeric 'frame' and 'speed'.
    """
    rows = table.get("rows", [])
    hdr = table.get("columns", [])
    recs = []
    for row in rows:
        rec = dict(zip(hdr, row))
        try:
            rec["frame"] = int(rec["frame"])
            rec["speed"] = float(rec["speed"])
        except (KeyError, ValueError):
            continue
        recs.append(rec)
    return recs

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """
    Every distinct entity that appears in the scope, with its full human‑readable description.
    The ids are the identifiers every other function uses for these entities.
    """
    ents = {}
    # Find the 'Video #: Objects' node
    objects_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Objects"):
            objects_node = node
            break
    if not objects_node:
        return []

    objects_lines = objects_node.get("lines", [])
    objects_map = _parse_objects(objects_lines)
    ents.update(objects_map)

    # In case a participant is referenced in events but not listed (unlikely), we still add it
    # Parse all event lines to collect any unknown object ids
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            for line in node.get("lines", []):
                for oid in _object_ids_from_lines([line]):
                    if oid not in ents:
                        ents[oid] = oid  # fallback description
    return [{"id": k, "description": v} for k, v in sorted(ents.items())]

def recorded_end(doc: Dict[str, Any], scope: str) -> float:
    """
    The last time point covered by the scope's records (in the document's own time unit).
    For CLEVRER videos this is the highest frame number in the motion log table.
    """
    # find the motion log table
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "table" and node.get("title", "").endswith(": Motion log"):
            table = node.get("table", {})
            rows = _parse_motion_log_table(table)
            if not rows:
                return 0.0
            max_frame = max(r["frame"] for r in rows)
            return float(max_frame)
    return 0.0

def observed_events(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """
    Every interaction event (involving two or more entities) recorded for the scope,
    in time order, with time in the same unit as recorded_end.
    """
    events = []

    # Parse event list node
    events_node = None
    for node in scope_nodes(doc, scope):
        if node.get("kind") == "list" and node.get("title", "").endswith(": Events"):
            events_node = node
            break
    if not events_node:
        return []

    # Time of recorded_end for conversion, but frames are already in same units
    # We'll keep time as float(frame)
    for line in events_node.get("lines", []):
        # Detect collisions
        if "collide" not in line.lower():
            continue

        # Extract frame
        frame_match = re.search(r'Frame\s+(\d+)', line)
        if not frame_match:
            continue
        frame = int(frame_match.group(1))

        # Determine kind: here only collision
        kind = "collision"

        # Extract participant ids
        participants = _object_ids_from_lines([line])
        # Ensure at least two
        if len(participants) < 2:
            # try regex for patterns like "Object 1 collides with Object 2"
            m = re.findall(r'Object (\d+)', line)
            participants = [f"Object {n}" for n in m]
        if len(participants) < 2:
            continue  # not a valid interaction

        events.append({
            "time": float(frame),
            "kind": kind,
            "participants": participants
        })

    # Sort by time
    events.sort(key=lambda e: e["time"])
    return events

