import math
import itertools
from collections import defaultdict, Counter

def all_scopes(doc):
    return [n["title"] for n in doc["nodes"] if n.get("kind")=="list" and n.get("title","").startswith("Video ")]

def motion_rows(scope):
    for node in scope_nodes(doc, scope):
        if node.get("kind")=="table" and node.get("title").endswith(": Motion log"):
            return _parse_motion_log_table(node["table"])
    return []

def avg_speed_change_per_frame():
    speed_change = defaultdict(list)
    for scope in all_scopes(doc):
        rows = motion_rows(scope)
        rows.sort(key=lambda r: (r["frame"], r["object"]))
        for obj, grp in itertools.groupby(rows, key=lambda r: r["object"]):
            grp = list(grp)
            prev = None
            for r in grp:
                if prev is not None:
                    speed_change[obj].append(r["speed"] - prev)
                prev = r["speed"]
    mean_changes = {obj: sum(v)/len(v) for obj, v in speed_change.items() if v}
    return mean_changes

def collision_stats():
    coll_info = []
    for scope in all_scopes(doc):
        for ev in observed_events(doc, scope):
            if ev["kind"] != "collision":
                continue
            t = int(ev["time"])
            rows = motion_rows(scope)
            pos = {r["object"]: (float(r["x"]), float(r["y"]), float(r["vx"]), float(r["vy"])) 
                   for r in rows if r["frame"]==t}
            if len(ev["participants"])<2 or ev["participants"][0] not in pos or ev["participants"][1] not in pos:
                continue
            p1, p2 = pos[ev["participants"][0]], pos[ev["participants"][1]]
            dist = math.dist(p1[:2], p2[:2])
            speed1 = math.hypot(p1[2], p1[3])
            speed2 = math.hypot(p2[2], p2[3])
            coll_info.append((scope, ev["time"], dist, speed1, speed2))
    return coll_info

# 1. Speed decay statistics
speed_changes = avg_speed_change_per_frame()
print("\nAverage speed change per frame for 10 objects:")
for obj, delta in list(speed_changes.items())[:10]:
    print(f"{obj}: {delta:.3f}")

# 2. Collision distance and speed distribution
colls = collision_stats()
print("\nNumber of recorded collisions:", len(colls))
print("\nFirst 5 collisions:")
for c in colls[:5]:
    print(c)
# estimate radius per collision (half the distance)
radii = [dist/2 for _,_,dist,_,_ in colls]
if radii:
    print("\nEstimated radius distribution (min,max,mean):", min(radii), max(radii), sum(radii)/len(radii))

# 3. Frame time unit (int frame indices)
print("\nTime unit: one frame = 1.0 time unit.")

# 4. Collision distance histogram
cnt = Counter(round(r,2) for r in radii)
print("\nRadius histogram (rounded to 0.01):")
for d in sorted(cnt)[:10]:
    print(d, cnt[d])

# 5. Early vs late collisions: relative speeds
speeds_before = [ (s1+s2)/2 for _,_,_,s1,s2 in colls]
print("\nAverage inter‑object speed at collision:", sum(speeds_before)/len(speeds_before))

