import math
import re
import statistics
from collections import defaultdict

# --------------------------------------------------------------------------- #
# 1. Count how many position samples exist per object across all scopes.
# --------------------------------------------------------------------------- #
samples_per_object = defaultdict(int)
for node in doc["nodes"]:
    if node.get("kind") != "table" or not node.get("title", "").endswith(": Motion log"):
        continue
    rows = _parse_motion_log_table(node.get("table", {}))
    for r in rows:
        oid_match = re.match(r"(\d+)\s", r["object"])
        if oid_match:
            oid = f"Object {oid_match.group(1)}"
            samples_per_object[oid] += 1

print("Samples per object (top 5):")
for oid, count in sorted(samples_per_object.items(), key=lambda x: -x[1])[:5]:
    print(f"  {oid}: {count} records")

# --------------------------------------------------------------------------- #
# 2. Compute average speed decay per frame for moving objects
# --------------------------------------------------------------------------- #
decay_rates = []
for node in doc["nodes"]:
    if node.get("kind") != "table" or not node.get("title", "").endswith(": Motion log"):
        continue
    rows = _parse_motion_log_table(node.get("table", {}))
    # group by object
    obj_rows: defaultdict = defaultdict(list)
    for r in rows:
        oid_match = re.match(r"(\d+)\s", r["object"])
        if oid_match:
            oid = f"Object {oid_match.group(1)}"
            obj_rows[oid].append(r)
    for oid, recs in obj_rows.items():
        recs_sorted = sorted(recs, key=lambda r: r["frame"])
        for i in range(1, len(recs_sorted)):
            vprev = recs_sorted[i-1]["speed"]
            vnext = recs_sorted[i]["speed"]
            if vprev > 0.1 and vprev - vnext > 0:
                decay_rates.append((vprev - vnext))

print("\nAverage speed decay per frame across all moving objects:", statistics.mean(decay_rates))

# --------------------------------------------------------------------------- #
# 3. Get approximate collision distance by analysing frames where collision
#    events are recorded.
# --------------------------------------------------------------------------- #
collision_dists = []
for node in doc["nodes"]:
    if node.get("kind") != "list" or not node.get("title", "").endswith(": Events"):
        continue
    scope_title = node["title"].rsplit(": ", 1)[0]
    event_lines = node["lines"]
    # collect collision frames
    coll_frames = {}
    for line in event_lines:
        if "collide" not in line.lower():
            continue
        f_match = re.search(r"Frame\s+(\d+)", line)
        if f_match:
            coll_frames.setdefault(int(f_match.group(1)), []).append(line)

    # load motion log for that scope
    motion_node = None
    for n in scope_nodes(doc, scope_title):
        if n.get("kind") == "table" and n.get("title", "").endswith(": Motion log"):
            motion_node = n
            break
    if not motion_node:
        continue
    rows = _parse_motion_log_table(motion_node.get("table", {}))
    pos_by_frame: defaultdict = defaultdict(dict)
    for r in rows:
        fid = r["frame"]
        oid_match = re.match(r"(\d+)\s", r["object"])
        if oid_match:
            oid = f"Object {oid_match.group(1)}"
            pos_by_frame[fid][oid] = (float(r["x"]), float(r["y"]))

    for f, lines in coll_frames.items():
        if f not in pos_by_frame:
            continue
        poses = pos_by_frame[f]
        # look for pair with minimal distance
        ids = list(poses.keys())
        if len(ids) < 2:
            continue
        for i in range(len(ids)):
            for j in range(i+1, len(ids)):
                x1, y1 = poses[ids[i]]
                x2, y2 = poses[ids[j]]
                dist = math.hypot(x1 - x2, y1 - y2)
                collision_dists.append(dist)

print("\nTypical collision distance (median):", statistics.median(collision_dists))
